mapper.select:
SELECT * FROM ( SELECT ROW_NUMBER() OVER (ORDER BY i.submitted_at DESC) AS rn, i.inspection_id AS inspectionId, i.submitted_at AS submittedAt, i.result AS result, i.facility_id AS facilityId, f.domain AS domain, f.name AS facilityName, f.floor AS floor, f.zone AS zone, i.inspector_id AS inspectorId, ip.name AS inspectorName FROM inspections i JOIN facilities f ON f.facility_id = i.facility_id LEFT JOIN inspector_profile ip ON ip.inspector_id = i.inspector_id WHERE 1=1
AND (LOWER(f.name) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(ip.name) LIKE '%' || LOWER(#{keyword}) || '%')
AND i.submitted_at BETWEEN #{startDate} AND #{endDate}
AND i.result = #{status}
) WHERE rn BETWEEN #{startRow} AND #{endRow}

SELECT COUNT(*) FROM inspections i JOIN facilities f ON f.facility_id = i.facility_id LEFT JOIN inspector_profile ip ON ip.inspector_id = i.inspector_id WHERE 1=1
AND (LOWER(f.name) LIKE '%' || LOWER(#{keyword}) || '%' OR LOWER(ip.name) LIKE '%' || LOWER(#{keyword}) || '%')
AND i.submitted_at BETWEEN #{startDate} AND #{endDate}
AND i.result = #{status}
